@@ -0,0 +1,38 @@
+import type { Migration } from './types';
+
+const migration051: Migration = {
+  version: 51,
+  name: 'matches-item-pair-unique',
+  up(db) {
+    // Drop the old (cargo_id, vessel_id, user_id) unique index — it collapsed all items
+    // from the same email pair into a single row, losing the second cargo silently.
+    db.exec(`DROP INDEX IF EXISTS idx_matches_unique_cargo_vessel_user`);
+
+    // Remove any duplicates that violate the new key before creating the index.
+    // Keep the row with the lowest rowid (earliest insert = best-fit per existing sort).
+    db.exec(`
+      DELETE FROM matches
+      WHERE rowid NOT IN (
+        SELECT MIN(rowid) FROM matches
+        GROUP BY cargo_id, vessel_id, COALESCE(user_id, ''),
+                 COALESCE(cargo_item_index, 0), COALESCE(vessel_item_index, 0)
+      )
+    `);
+
+    // New unique index: uniqueness per item-pair, not per email-pair.
+    db.exec(`
+      CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_unique_item_pair
+      ON matches(cargo_id, vessel_id, COALESCE(user_id, ''),
+                 COALESCE(cargo_item_index, 0), COALESCE(vessel_item_index, 0))
+    `);
+  },
+  down(db) {
+    db.exec(`DROP INDEX IF EXISTS idx_matches_unique_item_pair`);
+    db.exec(`
+      CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_unique_cargo_vessel_user
+      ON matches(cargo_id, vessel_id, COALESCE(user_id, ''))
+    `);
+  },
+};
+
+export default migration051;
