diff --git a/lib/migrations/051-matches-item-pair-unique.ts b/lib/migrations/051-matches-item-pair-unique.ts
new file mode 100644
index 00000000..cf6878a4
--- /dev/null
+++ b/lib/migrations/051-matches-item-pair-unique.ts
@@ -0,0 +1,53 @@
+import type { Migration } from './types';
+
+/**
+ * Expand the matches unique constraint to include item indices.
+ *
+ * Migration 034 created idx_matches_unique_cargo_vessel_user on
+ * (cargo_id, vessel_id, COALESCE(user_id, '')). This means only one match
+ * per (cargo email, vessel email) pair was allowed, silently discarding the
+ * second cargo/vessel item from the same email letter.
+ *
+ * This migration replaces that index with one that includes item indices so
+ * each (cargo email, cargo item, vessel email, vessel item) combination is
+ * a distinct row.
+ */
+const migration051: Migration = {
+  version: 51,
+  name: 'matches-item-pair-unique',
+  up(db) {
+    // Drop the old 3-column unique index.
+    db.exec(`DROP INDEX IF EXISTS idx_matches_unique_cargo_vessel_user`);
+
+    // Dedup: keep the earliest row per 5-column key as a safety guard.
+    // In practice, the old 3-column unique index prevented any duplicates on
+    // (cargo_id, vessel_id, user_id), so there are no conflicts to resolve here.
+    db.exec(`
+      DELETE FROM matches
+      WHERE rowid NOT IN (
+        SELECT MIN(rowid)
+        FROM matches
+        GROUP BY cargo_id, vessel_id, COALESCE(user_id, ''),
+                 COALESCE(cargo_item_index, 0), COALESCE(vessel_item_index, 0)
+      )
+    `);
+
+    // New 5-column unique index: one row per item-pair per user.
+    db.exec(`
+      CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_unique_item_pair
+      ON matches(
+        cargo_id, vessel_id, COALESCE(user_id, ''),
+        COALESCE(cargo_item_index, 0), COALESCE(vessel_item_index, 0)
+      )
+    `);
+  },
+  down(db) {
+    db.exec(`DROP INDEX IF EXISTS idx_matches_unique_item_pair`);
+    db.exec(`
+      CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_unique_cargo_vessel_user
+      ON matches(cargo_id, vessel_id, COALESCE(user_id, ''))
+    `);
+  },
+};
+
+export default migration051;
